{
}

Method.Source:
private void writeKCS_KBVBuildingProjectTable(Niedax.AX.TableRecordModels.TableRecord _record)
{
    System.Exception ex;

    Niedax.AX.TableRecordModels.KCS_KBVBuildingProjectTable kcs_KBVBuildingProjectTable = _record;
    KCS_KBVBuildingProjectTable lKCS_KBVBuildingProjectTable;
    KCS_KBVBuildingProjectID buildingProjectId = '';

    str message = strFmt("KCS_KBVBuildingProjectTable %1 entered on %2", kcs_KBVBuildingProjectTable.ToString(), this.environment);

    try
    {
        buildingProjectId = kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectId;
        if(_record.IsAX2009 && kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectId.Length < 7)
        {
            for(int i = 0; i< 7 - kcs_KBVBuildingProjectTable.KCS_KBVBuildingProjectId.Length; i++)
            {
                buildingProjectId = strIns(buildingProjectId, '0', 0);
            }
        }

        lKCS_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::find(buildingProjectId);

        //Make only updates on an existing record, since the records are created by determination process in d365
        if(!lKCS_KBVBuildingProjectTable)
        {
            message = strFmt("Record does not exist",  this.environment, kcs_KBVBuildingProjectTable.ToString());
            throw Error(message);
        }
        else
        {
            message = strFmt("KCS_KBVBuildingProjectTable %1 inserted or found on %2", lKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID, this.environment);
            response.RecId = lKCS_KBVBuildingProjectTable.RecId;
            response.Success = true;
        }

    }
    catch(ex)
    {
        message = message + "-" + ex.Message;
        response.RecId = 0;
    }

    response.Message = message;
}

/// <summary>
/// Updates or creates corresponding record
/// </summary>
/// <param name = "_record">record instance</param>
/// <returns>Response</returns>
public Niedax.D365.API.Models.D365_APIResponse writeRecord(Niedax.AX.TableRecordModels.TableRecord _record)
{
    this.writeKCS_KBVBuildingProjectTable(_record);
    return response;
}
